// Black-box reimplementation of the bech32 reference `convertbits`.
// All shifts/masks are done arithmetically (2**n, multiplication, Math.floor,
// modulo) because JS bitwise operators are 32-bit and shift amounts are taken
// mod 32, which would corrupt results for larger bit counts.

export function convertbits(data, frombits, tobits, pad = true) {
  let acc = 0;
  let bits = 0;
  const ret = [];
  const maxv = 2 ** tobits - 1;
  const maxAcc = 2 ** (frombits + tobits - 1) - 1;

  for (const value of data) {
    // value < 0 or (value >> frombits) != 0  →  invalid
    if (value < 0 || Math.floor(value / 2 ** frombits) !== 0) {
      return null;
    }
    // acc = ((acc << frombits) | value) & max_acc
    acc = (acc * 2 ** frombits + value) % (maxAcc + 1);
    bits += frombits;
    while (bits >= tobits) {
      bits -= tobits;
      // ret.push((acc >> bits) & maxv)
      ret.push(Math.floor(acc / 2 ** bits) % (maxv + 1));
    }
  }

  if (pad) {
    if (bits !== 0) {
      // ret.push((acc << (tobits - bits)) & maxv)
      ret.push((acc * 2 ** (tobits - bits)) % (maxv + 1));
    }
  } else {
    // bits >= frombits or ((acc << (tobits - bits)) & maxv) != 0  →  invalid
    if (bits >= frombits || (acc * 2 ** (tobits - bits)) % (maxv + 1) !== 0) {
      return null;
    }
  }

  return ret;
}
```

