```js
// Minimal manual argv parser mimicking Python's argparse for exactly the
// four required options of test14: --a (string), --b/--c/--d (ints).
// No npm dependencies; mirrors the reference executable's behavior
// (usage/error text, exit codes 0/2).

import process from 'node:process';

const PROG = 'test14.mjs';
const USAGE = `usage: ${PROG} [-h] --a A --b B --c C --d D`;

const HELP = `${USAGE}

options:
  -h, --help  show this help message and exit
  --a A
  --b B
  --c C
  --d D
`;

// Option declarations, in declaration order (required-error order matters).
const OPTIONS = [
  { name: '--a', metavar: 'A', type: 'str' },
  { name: '--b', metavar: 'B', type: 'int' },
  { name: '--c', metavar: 'C', type: 'int' },
  { name: '--d', metavar: 'D', type: 'int' },
];
const LONG_NAMES = ['--help', ...OPTIONS.map((o) => o.name)];

// Python repr() of a string, close enough for argparse/ValueError messages.
export function pyRepr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (code < 0x20 || code === 0x7f) {
      out += '\\x' + code.toString(16).padStart(2, '0');
    } else out += ch;
  }
  return out + quote;
}

// Python int() semantics: strip surrounding whitespace, optional +/- sign,
// decimal digits, single underscores allowed between digits (PEP 515).
// Returns { ok: true, value: number } or { ok: false }.
export function pyIntParse(s) {
  const m = /^\s*([+-]?\d+(?:_\d+)*)\s*$/.exec(s);
  if (!m) return { ok: false };
  return { ok: true, value: Number(m[1].replace(/_/g, '')) };
}

function fail(message) {
  process.stderr.write(`${USAGE}\n${PROG}: error: ${message}\n`);
  process.exit(2);
}

function printHelpAndExit() {
  process.stdout.write(HELP);
  process.exit(0);
}

// argparse's negative-number matcher; since no option strings look like
// negative numbers, tokens matching this are treated as values.
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

// Classify a token the way argparse does: 'O' = option-like, 'A' = value.
function classify(token) {
  if (!token.startsWith('-') || token === '-') return 'A';
  if (NEGATIVE_NUMBER.test(token)) return 'A';
  if (token.includes(' ')) return 'A';
  return 'O';
}

// Resolve an option string (without any "=value" part) to a declaration.
// Returns one of: 'help', an OPTIONS entry, null (unknown), or
// { ambiguous: [...] } for an ambiguous abbreviation.
function resolveOption(optString) {
  if (optString === '-h' || optString === '--help') return 'help';
  const exact = OPTIONS.find((o) => o.name === optString);
  if (exact) return exact;
  if (optString.startsWith('--')) {
    const matches = LONG_NAMES.filter((n) => n.startsWith(optString));
    if (matches.length === 1) {
      return matches[0] === '--help'
        ? 'help'
        : OPTIONS.find((o) => o.name === matches[0]);
    }
    if (matches.length > 1) return { ambiguous: matches };
  }
  return null;
}

// Parse argv (already sliced, i.e. without node/script path) into
// { a, b, c, d }. Prints argparse-style errors / help and exits the process
// on failure (exit 2) or --help (exit 0), exactly like Python argparse.
export function parseArgs(argv) {
  const values = {};
  const extras = [];
  let seenSeparator = false;

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];

    if (seenSeparator) {
      extras.push(token);
      continue;
    }
    if (token === '--') {
      seenSeparator = true; // everything after the first '--' is positional
      continue;
    }
    if (classify(token) === 'A') {
      extras.push(token); // unexpected positional
      continue;
    }

    // Option-like token: split "--opt=value" on the first '='.
    const eq = token.indexOf('=');
    const optString = eq === -1 ? token : token.slice(0, eq);
    const explicitValue = eq === -1 ? null : token.slice(eq + 1);

    const resolved = resolveOption(optString);
    if (resolved === 'help') {
      printHelpAndExit();
    } else if (resolved === null) {
      extras.push(token); // unrecognized option; argparse reports it at the end
      continue;
    } else if (resolved.ambiguous) {
      fail(
        `ambiguous option: ${optString} could match ${resolved.ambiguous.join(', ')}`,
      );
    }

    const option = resolved;
    let rawValue;
    if (explicitValue !== null) {
      rawValue = explicitValue;
    } else if (i + 1 < argv.length && classify(argv[i + 1]) === 'A') {
      rawValue = argv[++i];
    } else {
      fail(`argument ${option.name}: expected one argument`);
    }

    if (option.type === 'int') {
      const parsed = pyIntParse(rawValue);
      if (!parsed.ok) {
        fail(
          `argument ${option.name}: invalid int value: ${pyRepr(rawValue)}`,
        );
      }
      values[option.name.slice(2)] = parsed.value;
    } else {
      values[option.name.slice(2)] = rawValue;
    }
  }

  // Missing required options are reported before unrecognized arguments,
  // matching argparse (required check happens inside parse_known_args).
  const missing = OPTIONS.filter((o) => !(o.name.slice(2) in values)).map(
    (o) => o.name,
  );
  if (missing.length > 0) {
    fail(`the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length > 0) {
    fail(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return values;
}
